n    // NetworkError's are not correctly reflected by the plugin status which prevents reloading plugin\n    if (error && typeof error === 'string' && error.indexOf('NetworkError') > -1) {\n        pluginStatus = status.error;\n    }\n\n    if (_completionCallback) {\n        _completionCallback(error);\n    }\n};\n\nfunction sendPluginStateToWorker() {\n    evented.fire(new Event('pluginStateChange', {pluginStatus, pluginURL}));\n}\n\nexport const evented = new Evented();\n\nexport const getRTLTextPluginStatus = function () {\n    return pluginStatus;\n};\n\nexport const registerForPluginStateChange = function(callback: PluginStateSyncCallback) {\n    // Do an initial sync of the state\n    callback({pluginStatus, pluginURL});\n    // Listen for all future state changes\n    evented.on('pluginStateChange', callback);\n    return callback;\n};\n\nexport const clearRTLTextPlugin = function() {\n    pluginStatus = status.unavailable;\n    pluginURL = null;\n};\n\nexport const setRTLTextPlugin = function(url: string, callback: ?ErrorCallback, deferred: boolean = false) {\n    if (pluginStatus === status.deferred || pluginStatus === status.loading || pluginStatus === status.loaded) {\n        throw new Error('setRTLTextPlugin cannot be called multiple times.');\n    }\n    pluginURL = browser.resolveURL(url);\n    pluginStatus = status.deferred;\n    _completionCallback = callback;\n    sendPluginStateToWorker();\n\n    //Start downloading the plugin immediately if not intending to lazy-load\n    if (!deferred) {\n        downloadRTLTextPlugin();\n    }\n};\n\nexport const downloadRTLTextPlugin = function() {\n    if (pluginStatus !== status.deferred || !pluginURL) {\n        throw new Error('rtl-text-plugin cannot be downloaded unless a pluginURL is specified');\n    }\n    pluginStatus = status.loading;\n    sendPluginStateToWorker();\n    if (pluginURL) {\n        getArrayBuffer({url: pluginURL}, (error) => {\n            if (error) {\n                triggerPluginCompletionEvent(error);\n            } else {\n                pluginStatus = status.loaded;\n                sendPluginStateToWorker();\n            }\n        });\n    }\n};\n\nexport const plugin: {\n    applyArabicShaping: ?Function,\n    processBidirectionalText: ?(string, Array<number>) => Array<string>,\n    processStyledBidirectionalText: ?(string, Array<number>, Array<number>) => Array<[string, Array<number>]>,\n    isLoaded: () => boolean,\n    isLoading: () => boolean,\n    setState: (state: PluginState) => void,\n    isParsed: () => boolean,\n    getPluginURL: () => ?string\n} = {\n    applyArabicShaping: null,\n    processBidirectionalText: null,\n    processStyledBidirectionalText: null,\n    isLoaded() {\n        return pluginStatus === status.loaded || // Main Thread: loaded if the completion callback returned successfully\n            plugin.applyArabicShaping != null; // Web-worker: loaded if the plugin functions have been compiled\n    },\n    isLoading() { // Main Thread Only: query the loading status, this function does not return the correct value in the worker context.\n        return pluginStatus === status.loading;\n    },\n    setState(state: PluginState) { // Worker thread only: this tells the worker threads that the plugin is available on the Main thread\n        assert(isWorker(), 'Cannot set the state of the rtl-text-plugin when not in the web-worker context');\n\n        pluginStatus = state.pluginStatus;\n        pluginURL = state.pluginURL;\n    },\n    isParsed(): boolean {\n        assert(isWorker(), 'rtl-text-plugin is only parsed on the worker-threads');\n\n        return plugin.applyArabicShaping != null &&\n            plugin.processBidirectionalText != null &&\n            plugin.processStyledBidirectionalText != null;\n    },\n    getPluginURL(): ?string {\n        assert(isWorker(), 'rtl-text-plugin url can only be queried from the worker threads');\n        return pluginURL;\n    }\n};\n\nexport const lazyLoadRTLTextPlugin = function() {\n    if (!plugin.isLoading() &&\n        !plugin.isLoaded() &&\n        getRTLTextPluginStatus() === 'deferred'\n    ) {\n        downloadRTLTextPlugin();\n    }\n};\n", "// @flow\n\nimport ZoomHistory from './zoom_history';\nimport {isStringInSupportedScript} from '../util/script_detection';\nimport {plugin as rtlTextPlugin} from '../source/rtl_text_plugin';\n\nimport type {TransitionSpecification} from '../style-spec/types';\n\nexport type CrossfadeParameters = {\n    fromScale: number,\n    toScale: number,\n    t: number\n};\n\nclass EvaluationParameters {\n    zoom: number;\n    now: number;\n    fadeDuration: number;\n    zoomHistory: ZoomHistory;\n    transition: TransitionSpecification;\n\n    // \"options\" may also be another EvaluationParameters to copy, see CrossFadedProperty.possiblyEvaluate\n    constructor(zoom: number, options?: *) {\n        this.zoom = zoom;\n\n        if (options) {\n            this.now = options.now;\n            this.fadeDuration = options.fadeDuration;\n            this.zoomHistory = options.zoomHistory;\n            this.transition = options.transition;\n        } else {\n            this.now = 0;\n            this.fadeDuration = 0;\n            this.zoomHistory = new ZoomHistory();\n            this.transition = {};\n        }\n    }\n\n    isSupportedScript(str: string): boolean {\n        return isStringInSupportedScript(str, rtlTextPlugin.isLoaded());\n    }\n\n    crossFadingFactor() {\n        if (this.fadeDuration === 0) {\n            return 1;\n        } else {\n            return Math.min((this.now - this.zoomHistory.lastIntegerZoomTime) / this.fadeDuration, 1);\n        }\n    }\n\n    getCrossfadeParameters(): CrossfadeParameters {\n        const z = this.zoom;\n        const fraction = z - Math.floor(z);\n        const t = this.crossFadingFactor();\n\n        return z > this.zoomHistory.lastIntegerZoom ?\n            {fromScale: 2, toScale: 1, t: fraction + (1 - fraction) * t} :\n            {fromScale: 0.5, toScale: 1, t: 1 - (1 - t) * fraction};\n    }\n}\n\nexport default EvaluationParameters;\n", "// @flow\n\nimport assert from 'assert';\nimport {clone, extend, easeCubicInOut} from '../util/util';\nimport * as interpolate from '../style-spec/util/interpolate';\nimport {normalizePropertyExpression} from '../style-spec/expression';\nimport Color from '../style-spec/util/color';\nimport {register} from '../util/web_worker_transfer';\nimport EvaluationParameters from './evaluation_parameters';\n\nimport type {CanonicalTileID} from '../source/tile_id';\nimport type {StylePropertySpecification} from '../style-spec/style-spec';\nimport type {\n    TransitionSpecification,\n    PropertyValueSpecification\n} from '../style-spec/types';\n\nimport type {\n    Feature,\n    FeatureState,\n    StylePropertyExpression,\n    SourceExpression,\n    CompositeExpression\n} from '../style-spec/expression';\n\ntype TimePoint = number;\n\nexport type CrossFaded<T> = {\n    to: T,\n    from: T\n};\n\n/**\n * Implements a number of classes that define state and behavior for paint and layout properties, most\n * importantly their respective evaluation chains:\n *\n *       Transitionable paint property value\n *     → Transitioning paint property value\n *     → Possibly evaluated paint property value\n *     → Fully evaluated paint property value\n *\n *       Layout property value\n *     → Possibly evaluated layout property value\n *     → Fully evaluated layout property value\n *\n * @module\n * @private\n */\n\n/**\n *  Implementations of the `Property` interface:\n *\n *  * Hold metadata about a property that's independent of any specific value: stuff like the type of the value,\n *    the default value, etc. This comes from the style specification JSON.\n *  * Define behavior that needs to be polymorphic across different properties: \"possibly evaluating\"\n *    an input value (see below), and interpolating between two possibly-evaluted values.\n *\n *  The type `T` is the